using Microsoft.AspNetCore.Components;
using sv_ab466aec5b57438e93630b0bb0c42aef.Models;
using sv_ab466aec5b57438e93630b0bb0c42aef.Services;

namespace sv_ab466aec5b57438e93630b0bb0c42aef.Components.Pages;

public partial class Settings : ComponentBase
{
    private string activeSection = "Profile";
    private bool isLoading = true;
    private bool isSaving;
    private string? toastMessage;
    private string toastType = "toast-success";

    // Profile state
    private string profileDisplayName = string.Empty;
    private string profileEmail = string.Empty;
    private string profileBio = string.Empty;
    private string profileAvatarUrl = string.Empty;
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmailEnabled;
    private bool notifPushEnabled;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> availableChannels = new()
    {
        "General", "Engineering", "Design", "Marketing", "Sales", "Support", "Random"
    };

    // Security state
    private SecuritySettings? securitySettings;
    private bool twoFactorEnabled;
    private bool showPasswordPanel;
    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadActiveSection();
        isLoading = false;
    }

    private async Task SetActiveSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadActiveSection();
        isLoading = false;
    }

    private async Task LoadActiveSection()
    {
        switch (activeSection)
        {
            case "Profile":
                await LoadProfile();
                break;
            case "Notifications":
                await LoadNotifications();
                break;
            case "Security":
                await LoadSecurity();
                break;
            case "Appearance":
                await LoadAppearance();
                break;
        }
    }

    private async Task LoadProfile()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileAvatarUrl = profile.AvatarUrl;
    }

    private async Task LoadNotifications()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        notifEmailEnabled = prefs.EmailNotifications;
        notifPushEnabled = prefs.PushNotifications;
        notifWeeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new List<string>(prefs.MutedChannels);
    }

    private async Task LoadSecurity()
    {
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = securitySettings.TwoFactorEnabled;
    }

    private async Task LoadAppearance()
    {
        var appearance = await SettingsService.GetAppearanceAsync();
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompactMode = appearance.CompactMode;
    }

    private async Task SaveProfile()
    {
        isSaving = true;
        try
        {
            var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
            await SettingsService.SaveProfileAsync(profile);
            savedProfile = profile;
            ShowToast("Profile saved successfully!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving profile: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileBio = savedProfile.Bio;
            profileAvatarUrl = savedProfile.AvatarUrl;
        }
        ShowToast("Changes discarded.", "toast-info");
    }

    private async Task SaveNotificationPrefs()
    {
        isSaving = true;
        try
        {
            var prefs = new NotificationPrefs(notifEmailEnabled, notifPushEnabled, notifWeeklyDigest, new List<string>(mutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving preferences: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !mutedChannels.Contains(channel))
        {
            mutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            mutedChannels.Remove(channel);
        }
    }

    private void TogglePasswordPanel()
    {
        showPasswordPanel = !showPasswordPanel;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "toast-error");
            return;
        }

        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "toast-error");
            return;
        }

        isSaving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = string.Empty;
            newPassword = string.Empty;
            confirmPassword = string.Empty;
            showPasswordPanel = false;
            ShowToast("Password updated successfully!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error updating password: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke == null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            await LoadSecurity();
            ShowToast("Session revoked successfully.", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error revoking session: {ex.Message}", "toast-error");
        }
        finally
        {
            showRevokeConfirmation = false;
            sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task SaveAppearance()
    {
        isSaving = true;
        try
        {
            var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved!", "toast-success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error saving appearance: {ex.Message}", "toast-error");
        }
        finally
        {
            isSaving = false;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{appearanceTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{appearanceFontSize.ToLowerInvariant()}");
        if (appearanceCompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast()
    {
        toastMessage = null;
    }
}

