+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    padding: 2rem;
+    border-radius: 12px;
+    max-width: 450px;
+    width: 90%;
+    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
+}
+
+.modal-dialog h3 {
+    margin-top: 0;
+    margin-bottom: 1rem;
+}
+
+.modal-dialog p {
+    color: #555;
+    margin-bottom: 1.5rem;
+}
+
+/* Loading */
+.loading-spinner {
