+    font-size: 0.85rem;
+    color: #777;
+    margin-top: 0.5rem;
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .settings-container {
+        flex-direction: column;
+        padding: 1rem;
+    }
+
+    .settings-sidebar {
+        width: 100%;
+    }
+
+    .settings-nav {
+        display: flex;
+        overflow-x: auto;
+        position: static;
+    }
+
+    .settings-nav li {
+        white-space: nowrap;
+    }
+}
+

